#[test]
fn dsd512_round_trip_sine_amplitude_matches_within_1db() {
    // 0.05 s keeps the DSD512 test fast: 1.13M DSD samples.
    let pcm = sine_stereo_44100(0.05);
    let decoded = round_trip(DsdLevel::Dsd512, 44_100, 2, &pcm, 352_800);
    let left = channel(&decoded, 2, 0);
    // 352.8 kHz: skip 0.02 s (7056 frames), fit to 0.05 s.
    let amp = sine_amplitude(&left[7056..17640], 352_800.0, 1000.0);
    assert!((amp - 0.5).abs() < 0.05, "amplitude {amp}");
}

#[test]
fn dsd64_from_48khz_round_trip_sine_amplitude_matches() {
    // 48 kHz family: rational interpolation (588/10) to DSD64,
    // decoded back through the decimator's 48 kHz path.
    let pcm = sine_mono(48_000, 1000.0, 0.5, 0.1);
    let decoded = round_trip(DsdLevel::Dsd64, 48_000, 1, &pcm, 48_000);
    // Skip 0.02 s of warm-up, fit over the middle.
    let end = decoded.len() - 500.min(decoded.len() / 2);
    let amp = sine_amplitude(&decoded[960..end], 48_000.0, 1000.0);
    assert!((amp - 0.5).abs() < 0.05, "amplitude {amp}");
}

#[test]
fn thd_plus_n_of_1khz_sine_is_below_minus_60db() {
    let pcm = sine_mono(44_100, 1000.0, 0.5, 0.1);
    let decoded = round_trip(DsdLevel::Dsd64, 44_100, 1, &pcm, 44_100);
    // Settled window only: skip 0.02 s, stop before the flush
    // tail (the last ~500 frames are zero-padded audio).
    let window = &decoded[882..decoded.len().saturating_sub(500)];
    let (thd, resid_rms, resid_max) = thd_plus_n_db(window, 44_100.0, 1000.0);
    // Measured 2026-11-09 on this VM (debug build, through
    // the library decimator): THD+N -84.9 dB, residual RMS
    // 0.00002, residual max 0.00007. The threshold below keeps
    // 25 dB of margin under the measured value.
    println!(
        "measured dsd64 1 khz thd+n: {thd:.1} dB, residual rms {resid_rms:.5}, max {resid_max:.5}"
    );
    assert!(thd < -60.0, "thd+n {thd:.1} dB");
}

#[test]
fn silence_round_trip_stays_near_silence() {
    let pcm = vec![0.0f32; 4410];
    let decoded = round_trip(DsdLevel::Dsd64, 44_100, 1, &pcm, 44_100);
    let settled = &decoded[882..];
    assert!(rms(settled) < 0.01, "silence rms {}", rms(settled));
}

#[test]
#[allow(
    clippy::cast_precision_loss,
    reason = "the settled window holds a few thousand samples, far below 2^53"
)]
fn dc_round_trip_preserves_level() {
    let pcm = vec![0.5f32; 4410];
    let decoded = round_trip(DsdLevel::Dsd64, 44_100, 1, &pcm, 44_100);
    // Middle window: past the warm-up, before the flush tail.
    let settled = &decoded[882..decoded.len().saturating_sub(500)];
    let mean = settled.iter().map(|&v| f64::from(v)).sum::<f64>() / settled.len() as f64;
    assert!((mean - 0.5).abs() < 0.05, "dc mean {mean}");
}

// ------------------------------------------------------- containers (files)

#[test]
fn dsf_and_dff_files_read_back_and_decode_the_same_sine() {
    let pcm = sine_stereo_44100(0.1);
    let mut modulator = DsdModulator::new(DsdLevel::Dsd64, 44_100, 2).unwrap();
    let mut bytes = Vec::new();
    for chunk in pcm.chunks(512) {
        bytes.extend(modulator.feed(chunk).unwrap());
    }
    bytes.extend(modulator.flush().unwrap());
    let samples = modulator.dsd_samples_emitted();
    let dsf = write_dsf(&bytes, DsdLevel::Dsd64, 2, samples).unwrap();
    let dff = write_dff(&bytes, DsdLevel::Dsd64, 2).unwrap();

    let mut amps = Vec::new();
    for (name, file, layout) in [
        (
            "dsf",
            dsf,
            DsdBlockLayout::Dsf {
                block_size_per_channel: 4096,
            },
        ),
        ("dff", dff, DsdBlockLayout::Dff),
    ] {
        let mut demuxer = DsdDemuxer::new(Cursor::new(file)).unwrap();
        let header = demuxer.header().clone();
        assert_eq!(header.sample_rate, 2_822_400);
        assert_eq!(header.channels, 2);
        let mut decimator =
            DsdDecimator::new(header.sample_rate, header.channels, 44_100, layout).unwrap();
        let mut out = Vec::new();
        while let Some(packet) = demuxer.next_packet().unwrap() {
            out.extend(decimator.feed(&packet.data).unwrap());
        }
        out.extend(decimator.flush().unwrap());
        let left = channel(&out, 2, 0);
        let amp = sine_amplitude(&left[882..4410], 44_100.0, 1000.0);
        assert!((amp - 0.5).abs() < 0.05, "{name} amplitude {amp}");
        amps.push(amp);
    }
    // The two containers hold the same bits: their decoded
    // amplitudes must agree closely (this catches a bit-order
    // swap in either writer).
    assert!(
        (amps[0] - amps[1]).abs() < 0.02,
        "dsf {} vs dff {}",
        amps[0],
        amps[1]
    );
}

#[test]
fn dsdmod_fixtures_decode_to_the_expected_sine() {
    // Guards the checked-in fixtures against drift: the files
    // below are produced by `generate_dsdmod_fixtures`.
    for name in ["dsdmod_dsd64_stereo.dsf", "dsdmod_dsd128_stereo.dsf"] {
        let bytes = std::fs::read(format!("{DATA}/{name}")).unwrap();
        let mut demuxer = DsdDemuxer::new(Cursor::new(bytes)).unwrap();
        let header = demuxer.header().clone();
        let target = if header.sample_rate == 2_822_400 {
            44_100
        } else {
            176_400
        };
        let mut decimator =
            DsdDecimator::new(header.sample_rate, header.channels, target, header.layout())
                .unwrap();
        let mut out = Vec::new();
        while let Some(packet) = demuxer.next_packet().unwrap() {
            out.extend(decimator.feed(&packet.data).unwrap());
        }
        out.extend(decimator.flush().unwrap());
        let left = channel(&out, 2, 0);
        let skip = (target / 50) as usize;
        let end = (target / 10) as usize;
        let amp = sine_amplitude(&left[skip..end], f64::from(target), 1000.0);
        assert!((amp - 0.5).abs() < 0.05, "{name} amplitude {amp}");
    }
    let dff = std::fs::read(format!("{DATA}/dsdmod_dsd64_stereo.dff")).unwrap();
    let demuxer = DsdDemuxer::new(Cursor::new(dff)).unwrap();
    assert_eq!(demuxer.header().sample_rate, 2_822_400);
    assert_eq!(demuxer.header().channels, 2);
    let wav = std::fs::read(format!("{DATA}/dsdmod_sine_stereo_44100.wav")).unwrap();
    assert_eq!(&wav[0..4], b"RIFF");
    assert_eq!(&wav[8..12], b"WAVE");
}

// ------------------------------------------------------------- error paths

#[test]
fn invalid_pcm_rate_is_rejected() {
    for rate in [32_000, 22_050, 48_001] {
        let err = DsdModulator::new(DsdLevel::Dsd64, rate, 2).unwrap_err();
        assert!(
            matches!(err, codec_whatttttttttttt_core::Error::InvalidArgument(_)),
            "rate {rate}: {err:?}"
        );
    }
}

#[test]
fn partial_frame_input_is_rejected() {
    let mut modulator = DsdModulator::new(DsdLevel::Dsd64, 44_100, 2).unwrap();
    let err = modulator.feed(&[0.0, 0.0, 0.0]).unwrap_err();
    assert!(matches!(
        err,
        codec_whatttttttttttt_core::Error::InvalidArgument(_)
    ));
}

#[test]
fn feed_after_flush_is_rejected() {
    let mut modulator = DsdModulator::new(DsdLevel::Dsd64, 44_100, 1).unwrap();
    modulator.feed(&[0.0; 64]).unwrap();
    modulator.flush().unwrap();
    assert!(modulator.feed(&[0.0; 64]).is_err());
    assert!(modulator.flush().is_err());
}

#[test]
fn streaming_feed_in_small_blocks_matches_one_shot() {
    let pcm = sine_stereo_44100(0.05);
    let mut streamed = DsdModulator::new(DsdLevel::Dsd64, 44_100, 2).unwrap();
    let mut streamed_bytes = Vec::new();
    for chunk in pcm.chunks(128) {
        streamed_bytes.extend(streamed.feed(chunk).unwrap());
    }
    streamed_bytes.extend(streamed.flush().unwrap());
    let mut oneshot = DsdModulator::new(DsdLevel::Dsd64, 44_100, 2).unwrap();
    let mut oneshot_bytes = oneshot.feed(&pcm).unwrap();
    oneshot_bytes.extend(oneshot.flush().unwrap());
    assert_eq!(streamed_bytes, oneshot_bytes);
}

#[test]
fn loud_input_is_clamped_and_the_loop_recovers() {
    // A 0.9-amplitude sine overloads the loop if fed raw; the
    // modulator clamps to the verified-stable ±0.75 range, so
    // no overload reset is needed and a following 0.5 sine
    // still decodes at 0.5.
    let mut loud = sine_mono(44_100, 1000.0, 0.9, 0.05);
    loud.extend(sine_mono(44_100, 1000.0, 0.5, 0.05));
    let mut modulator = DsdModulator::new(DsdLevel::Dsd64, 44_100, 1).unwrap();
    let mut bytes = modulator.feed(&loud).unwrap();
    bytes.extend(modulator.flush().unwrap());
    assert!(modulator.clamped_samples() > 0, "nothing was clamped");
    assert_eq!(modulator.overload_count(), 0);
    let mut decimator = DsdDecimator::new(
        2_822_400,
        1,
        44_100,
        DsdBlockLayout::Dsf {
            block_size_per_channel: 4096,
        },
    )
    .unwrap();
    let mut out = Vec::new();
    for chunk in bytes.chunks(4096) {
        out.extend(decimator.feed(chunk).unwrap());
    }
    out.extend(decimator.flush().unwrap());
    // Second half (frames 2205..4410) is the 0.5 sine: skip its
    // first 0.02 s of settling after the loud burst.
    let amp = sine_amplitude(&out[3087..4410], 44_100.0, 1000.0);
    assert!((amp - 0.5).abs() < 0.05, "recovered amplitude {amp}");
    assert!(out.iter().all(|&v| v.is_finite() && v.abs() < 2.0));
}

// ------------------------------------------------------------- fixtures

/// Minimal 16-bit PCM WAV writer (RIFF, mono/stereo, no extra
/// chunks) for the source fixture.
#[allow(
    clippy::cast_possible_truncation,
    reason = "test fixtures are mono/stereo and a few seconds at most, so byte counts fit u32, channels fit u16, and samples are clamped to the i16 range before the final cast"
)]
fn write_wav_i16(samples: &[f32], sample_rate: u32, channels: u32) -> Vec<u8> {
    let data_bytes = samples.len() * 2;
    let mut out = Vec::with_capacity(44 + data_bytes);
    out.extend_from_slice(b"RIFF");
    out.extend_from_slice(&(36u32 + data_bytes as u32).to_le_bytes());
    out.extend_from_slice(b"WAVE");
    out.extend_from_slice(b"fmt ");
    out.extend_from_slice(&16u32.to_le_bytes());
    out.extend_from_slice(&1u16.to_le_bytes());
    out.extend_from_slice(&(channels as u16).to_le_bytes());
    out.extend_from_slice(&sample_rate.to_le_bytes());
    out.extend_from_slice(&(sample_rate * channels * 2).to_le_bytes());
    out.extend_from_slice(&(channels as u16 * 2).to_le_bytes());
    out.extend_from_slice(&16u16.to_le_bytes());
    out.extend_from_slice(b"data");
    out.extend_from_slice(&(data_bytes as u32).to_le_bytes());
    for &sample in samples {
        let value = (sample.clamp(-1.0, 1.0) * 32768.0).round() as i32;
        let value = value.clamp(i32::from(i16::MIN), i32::from(i16::MAX)) as i16;
        out.extend_from_slice(&value.to_le_bytes());
    }
    out
}

/// Generates the checked-in `dsdmod_*` fixtures. Ignored in
/// normal runs: it writes into `tests/data/`. Deterministic:
/// re-running it produces identical bytes.
#[test]
#[ignore = "writes checked-in fixtures into tests/data; run explicitly to regenerate"]
fn generate_dsdmod_fixtures() {
    let pcm = sine_stereo_44100(0.1);
    let wav = write_wav_i16(&pcm, 44_100, 2);
    std::fs::write(format!("{DATA}/dsdmod_sine_stereo_44100.wav"), wav).unwrap();
    for level in [DsdLevel::Dsd64, DsdLevel::Dsd128] {
        let mut modulator = DsdModulator::new(level, 44_100, 2).unwrap();
        let mut bytes = modulator.feed(&pcm).unwrap();
        bytes.extend(modulator.flush().unwrap());
        let samples = modulator.dsd_samples_emitted();
        let dsf = write_dsf(&bytes, level, 2, samples).unwrap();
        let stem = level.name();
        std::fs::write(format!("{DATA}/dsdmod_{stem}_stereo.dsf"), dsf).unwrap();
        // The DFF container is checked in for DSD64 only: the
        // DSF-to-DFF conversion is the same code at every
        // level, and the in-memory container test covers DSD128
        // conversion through the demuxer instead.
        if level == DsdLevel::Dsd64 {
            let dff = write_dff(&bytes, level, 2).unwrap();
            std::fs::write(format!("{DATA}/dsdmod_{stem}_stereo.dff"), dff).unwrap();
        }
    }
}

// ------------------------------------------------------------ benchmark
//
// Manual benchmark (not run in CI): `cargo test --release
// -p codec-whatttttttttttt-core --test dsd_modulate -- --ignored
// benchmark_modulate`. Measures modulate speed in x realtime
// on this VM and prints it; asserts only that the output is
// non-empty, so a slow machine fails nothing.
//
// Measured 2026-11-09 on this VM (release build, 0.5 s stereo
// 44.1 kHz in): DSD128 0.39x realtime, DSD512 0.12x realtime.
// The modulator is not realtime: the interpolator does 33
// scalar MACs per DSD sample per channel (same order of cost
// as the decimator, which measures 0.3x realtime at DSD512).
// A faster path would need SIMD or a shorter interpolation
// filter, not a different modulator.

#[test]
#[ignore = "manual benchmark, not run in CI; prints speed only"]
fn benchmark_modulate_dsd128_and_dsd512_speed() {
    use std::time::Instant;
    let pcm = sine_stereo_44100(0.5);
    for level in [DsdLevel::Dsd128, DsdLevel::Dsd512] {
        let mut modulator = DsdModulator::new(level, 44_100, 2).unwrap();
        let start = Instant::now();
        let mut bytes = Vec::new();
        for chunk in pcm.chunks(4096) {
            bytes.extend(modulator.feed(chunk).unwrap());
        }
        bytes.extend(modulator.flush().unwrap());
        let elapsed = start.elapsed().as_secs_f64();
        let audio_seconds = 0.5;
        let speed = audio_seconds / elapsed;
        println!(
            "{}: 0.5 s stereo in {elapsed:.3} s ({speed:.2}x realtime, {} dsd bytes)",
            level.name(),
            bytes.len()
        );
        assert_ne!(bytes, [] as [u8; 0]);
    }
}
